#include "cvc_diff.h"
#include <string.h>
#include <stdlib.h>
#include <limits.h>
#include <stdint.h>

typedef struct { size_t start,end; CvcBuf repl; int side; int dup; } Edit;
typedef struct { Edit *v; size_t n,cap; } Edits;

void cvc_lines_split(const unsigned char*p,size_t n,CvcLines*out){out->v=NULL;out->n=0;if(!n)return;size_t cap=16;out->v=cvc_xmalloc(cap*sizeof(*out->v));size_t st=0;for(size_t i=0;i<n;i++)if(p[i]=='\n'){if(out->n==cap){cap*=2;out->v=cvc_xrealloc(out->v,cap*sizeof(*out->v));}out->v[out->n++]=(CvcLine){p+st,i-st+1};st=i+1;}if(st<n){if(out->n==cap){cap*=2;out->v=cvc_xrealloc(out->v,cap*sizeof(*out->v));}out->v[out->n++]=(CvcLine){p+st,n-st};}}
void cvc_lines_free(CvcLines*l){free(l->v);l->v=NULL;l->n=0;}
static int leq(const CvcLine*a,const CvcLine*b){return a->n==b->n&&!memcmp(a->p,b->p,a->n);}
static void op_push(CvcDiffOps*o,char op,size_t a,size_t b){if(o->n==o->cap){o->cap=o->cap?o->cap*2:64;o->v=cvc_xrealloc(o->v,o->cap*sizeof(*o->v));}o->v[o->n++]=(CvcDiffOp){op,a,b};}
void cvc_diffops_free(CvcDiffOps*o){free(o->v);o->v=NULL;o->n=o->cap=0;}
int cvc_myers_diff(const CvcLines*a,const CvcLines*b,CvcDiffOps*out){out->v=NULL;out->n=out->cap=0;if(a->n>(size_t)INT_MAX||b->n>(size_t)INT_MAX)return cvc_errorf("too many lines for diff");int N=(int)a->n,M=(int)b->n,max=N+M,off=max+1,sz=2*max+3;int*V=cvc_xmalloc((size_t)sz*sizeof(int));for(int i=0;i<sz;i++)V[i]=-1;V[off+1]=0;int**trace=cvc_xcalloc((size_t)max+1,sizeof(*trace));int D=-1;for(int d=0;d<=max;d++){for(int k=-d;k<=d;k+=2){int idx=off+k,x;if(k==-d||(k!=d&&V[idx-1]<V[idx+1]))x=V[idx+1];else x=V[idx-1]+1;int y=x-k;while(x<N&&y<M&&leq(&a->v[x],&b->v[y])){x++;y++;}V[idx]=x;if(x>=N&&y>=M){D=d;break;}}trace[d]=cvc_xmalloc((size_t)sz*sizeof(int));memcpy(trace[d],V,(size_t)sz*sizeof(int));if(D>=0)break;}if(D<0){free(V);for(int d=0;d<=max;d++)free(trace[d]);free(trace);return cvc_errorf("Myers diff failed");}
CvcDiffOps rev={0};int x=N,y=M;for(int d=D;d>0;d--){int k=x-y;int*pv=trace[d-1];int pk;if(k==-d||(k!=d&&pv[off+k-1]<pv[off+k+1]))pk=k+1;else pk=k-1;int px=pv[off+pk],py=px-pk;while(x>px&&y>py){x--;y--;op_push(&rev,'=',(size_t)x,(size_t)y);}if(x==px){y--;op_push(&rev,'+',(size_t)x,(size_t)y);}else{x--;op_push(&rev,'-',(size_t)x,(size_t)y);}}
while(x>0&&y>0){x--;y--;op_push(&rev,'=',(size_t)x,(size_t)y);}while(x>0){x--;op_push(&rev,'-',(size_t)x,0);}while(y>0){y--;op_push(&rev,'+',0,(size_t)y);}for(size_t i=0;i<rev.n;i++){CvcDiffOp z=rev.v[rev.n-1-i];op_push(out,z.op,z.ai,z.bi);}cvc_diffops_free(&rev);free(V);for(int d=0;d<=D;d++)free(trace[d]);free(trace);return 0;}
void cvc_diff_counts(const CvcDiffOps*o,uint64_t*ins,uint64_t*del){*ins=*del=0;for(size_t i=0;i<o->n;i++){if(o->v[i].op=='+')(*ins)++;else if(o->v[i].op=='-')(*del)++;}}
static void edits_free(Edits*e){for(size_t i=0;i<e->n;i++)cvc_buf_free(&e->v[i].repl);free(e->v);e->v=NULL;e->n=e->cap=0;}
static void edit_push(Edits*e,Edit*x){if(e->n==e->cap){e->cap=e->cap?e->cap*2:16;e->v=cvc_xrealloc(e->v,e->cap*sizeof(*e->v));}e->v[e->n++]=*x;}
static int make_edits(const CvcLines*base,const CvcLines*side,int which,Edits*out){CvcDiffOps op;if(cvc_myers_diff(base,side,&op)<0)return -1;out->v=NULL;out->n=out->cap=0;size_t apos=0;Edit cur={0};int active=0;for(size_t i=0;i<op.n;i++){CvcDiffOp*z=&op.v[i];if(z->op=='='){if(active){edit_push(out,&cur);memset(&cur,0,sizeof(cur));active=0;}apos++;continue;}if(!active){cur.start=apos;cur.end=apos;cur.side=which;cvc_buf_init(&cur.repl);active=1;}if(z->op=='-'){cur.end++;apos++;}else if(z->op=='+')cvc_buf_append(&cur.repl,side->v[z->bi].p,side->v[z->bi].n);}if(active)edit_push(out,&cur);cvc_diffops_free(&op);return 0;}
static int edit_same(const Edit*a,const Edit*b){return a->start==b->start&&a->end==b->end&&a->repl.len==b->repl.len&&!memcmp(a->repl.data,b->repl.data,a->repl.len);}
static int edit_conflict(const Edit*a,const Edit*b){int ai=a->start==a->end,bi=b->start==b->end;if(ai&&bi)return a->start==b->start&&!edit_same(a,b);if(!ai&&!bi){size_t lo=a->start>b->start?a->start:b->start,hi=a->end<b->end?a->end:b->end;return lo<hi&&!edit_same(a,b);}const Edit*ins=ai?a:b,*wide=ai?b:a;return ins->start>wide->start&&ins->start<wide->end;}
static int cmp_edit(const void*aa,const void*bb){const Edit*a=*(Edit*const*)aa,*b=*(Edit*const*)bb;if(a->start!=b->start)return a->start<b->start?-1:1;int ai=a->start==a->end,bi=b->start==b->end;if(ai!=bi)return ai?-1:1;if(a->end!=b->end)return a->end<b->end?-1:1;return a->side-b->side;}
int cvc_three_way_text(const unsigned char*base,size_t bn,const unsigned char*ours,size_t on,const unsigned char*theirs,size_t tn,CvcBuf*result,int*conflict){*conflict=0;cvc_buf_init(result);if(on==tn&&!memcmp(ours,theirs,on)){cvc_buf_append(result,ours,on);return 0;}if(on==bn&&!memcmp(ours,base,on)){cvc_buf_append(result,theirs,tn);return 0;}if(tn==bn&&!memcmp(theirs,base,tn)){cvc_buf_append(result,ours,on);return 0;}CvcLines B,O,T;cvc_lines_split(base,bn,&B);cvc_lines_split(ours,on,&O);cvc_lines_split(theirs,tn,&T);Edits eo={0},et={0};if(make_edits(&B,&O,0,&eo)<0||make_edits(&B,&T,1,&et)<0){edits_free(&eo);edits_free(&et);cvc_lines_free(&B);cvc_lines_free(&O);cvc_lines_free(&T);return -1;}for(size_t i=0;i<eo.n;i++)for(size_t j=0;j<et.n;j++){if(edit_same(&eo.v[i],&et.v[j]))et.v[j].dup=1;else if(edit_conflict(&eo.v[i],&et.v[j]))*conflict=1;}if(*conflict){static const char a[]="<<<<<<< ours\n",m[]="=======\n",z[]=">>>>>>> theirs\n";cvc_buf_append(result,a,sizeof(a)-1);cvc_buf_append(result,ours,on);if(on&&ours[on-1]!='\n')cvc_buf_putc(result,'\n');cvc_buf_append(result,m,sizeof(m)-1);cvc_buf_append(result,theirs,tn);if(tn&&theirs[tn-1]!='\n')cvc_buf_putc(result,'\n');cvc_buf_append(result,z,sizeof(z)-1);}else{size_t cnt=eo.n;for(size_t j=0;j<et.n;j++)if(!et.v[j].dup)cnt++;Edit**all=cvc_xmalloc((cnt?cnt:1)*sizeof(*all));size_t k=0;for(size_t i=0;i<eo.n;i++)all[k++]=&eo.v[i];for(size_t j=0;j<et.n;j++)if(!et.v[j].dup)all[k++]=&et.v[j];qsort(all,k,sizeof(*all),cmp_edit);size_t pos=0;for(size_t i=0;i<k;i++){Edit*e=all[i];if(e->start<pos&&e->start!=e->end){free(all);edits_free(&eo);edits_free(&et);cvc_lines_free(&B);cvc_lines_free(&O);cvc_lines_free(&T);cvc_buf_free(result);return cvc_errorf("internal overlapping merge edits");}for(size_t q=pos;q<e->start;q++)cvc_buf_append(result,B.v[q].p,B.v[q].n);cvc_buf_append(result,e->repl.data,e->repl.len);if(e->end>pos)pos=e->end;}for(size_t q=pos;q<B.n;q++)cvc_buf_append(result,B.v[q].p,B.v[q].n);free(all);}edits_free(&eo);edits_free(&et);cvc_lines_free(&B);cvc_lines_free(&O);cvc_lines_free(&T);return 0;}
